<script setup>
import {computed,ref,watch,onBeforeUnmount,nextTick} from 'vue';
import {Button} from 'vant';import 'vant/es/button/style';
const props=defineProps({grade:{type:Object,required:true},question:{type:Object,required:true},paper:{type:Object,required:true},render:Function,gradingOnly:Boolean});
const canvases=new Map(),errors=ref({}),transcription=ref(false);let sequence=0,alive=true;
const verdict=v=>({correct:'正确',partial:'部分正确',incorrect:'需要订正',unanswered:'未作答',review:'待人工核对'})[v]||'待核对';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const html=s=>props.render?props.render(String(s||'')):window.GrowingMathFormat?.html(String(s||''))||escape(s);
const result=computed(()=>props.grade.result||{});
const annotations=computed(()=>result.value.answerAnnotations||[]);
const sources=computed(()=>{const pages=result.value.answerPages||[];if(pages.length)return pages.map((image,i)=>({image,page:i+1,handwritten:true}));if(props.grade.kind!=='initial')return [];const regions=result.value.answerRegions?.length?result.value.answerRegions:props.question.regions||[];return regions.map(region=>({region,page:region.page,image:props.paper.pages?.find(p=>p.page===region.page)?.image}));});
const at=computed(()=>props.grade.at&&Number.isFinite(Date.parse(props.grade.at))?new Date(props.grade.at).toLocaleString('zh-CN',{hour12:false}):'');
function validRegion(r){return r&&[r.x,r.y,r.width,r.height].every(Number.isFinite)&&r.x>=0&&r.y>=0&&r.width>0&&r.height>0&&r.x+r.width<=1.00001&&r.y+r.height<=1.00001;}
async function draw(){const run=++sequence;errors.value={};transcription.value=false;await nextTick();sources.value.forEach((source,i)=>{const canvas=canvases.get(i);if(!canvas)return;const image=new Image();const fail=message=>{if(alive&&run===sequence)errors.value={...errors.value,[i]:message};};if(!source.image||source.region&&!validRegion(source.region)){fail('本题原稿图片或定位范围缺失，请重新打开本题核对；批改记录仍保留。');return;}image.onerror=()=>fail('原稿图片加载失败，请重新打开本题；批改记录仍保留。');image.onload=()=>{if(!alive||run!==sequence||canvases.get(i)!==canvas)return;try{if(!image.naturalWidth||image.naturalWidth*image.naturalHeight>64000000)throw Error('原稿图片尺寸异常');const region={...(source.region||{x:0,y:0,width:1,height:1})};
   if(source.handwritten){const scan=document.createElement('canvas');scan.width=image.naturalWidth;scan.height=image.naturalHeight;const ctx=scan.getContext('2d');ctx.drawImage(image,0,0);const data=ctx.getImageData(0,0,scan.width,scan.height).data;let bottom=0;for(let y=scan.height-1;y>=0&&!bottom;y--)for(let x=0;x<scan.width;x++){const at=(y*scan.width+x)*4;if(data[at+3]>16&&data[at]+data[at+1]+data[at+2]<735){bottom=y+1;break;}}for(const mark of annotations.value)if(mark.page===source.page&&validRegion(mark))bottom=Math.max(bottom,(mark.y+mark.height)*scan.height);region.height=Math.min(1,Math.max(240,bottom+64)/scan.height);}
   const width=image.naturalWidth*region.width,height=image.naturalHeight*region.height,scaledHeight=Math.max(1,Math.round(800*height/width)),scale=Math.min(1,3000/scaledHeight);canvas.width=Math.max(1,Math.round(800*scale));canvas.height=Math.max(1,Math.round(scaledHeight*scale))+64;const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#b42318';ctx.font='bold 28px "Microsoft YaHei",sans-serif';ctx.fillText('第 '+source.page+' 页 · '+verdict(result.value.verdict),16,42);ctx.drawImage(image,image.naturalWidth*region.x,image.naturalHeight*region.y,width,height,0,64,canvas.width,canvas.height-64);ctx.fillStyle='#b42318';ctx.font='bold 64px sans-serif';ctx.fillText(result.value.verdict==='correct'?'✓':result.value.verdict==='incorrect'?'×':'?',canvas.width-76,132);
   if(!source.region)annotations.value.forEach((mark,index)=>{if(mark.page!==source.page||!validRegion(mark))return;const x=mark.x*canvas.width,y=64+mark.y/region.height*(canvas.height-64),w=mark.width*canvas.width,h=mark.height/region.height*(canvas.height-64);ctx.strokeStyle=ctx.fillStyle='#b42318';ctx.lineWidth=3;ctx.strokeRect(x,y,w,h);const cx=Math.max(14,Math.min(canvas.width-14,x)),cy=Math.max(80,y);ctx.beginPath();ctx.arc(cx,cy,13,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff';ctx.font='bold 16px sans-serif';ctx.textAlign='center';ctx.fillText(String(index+1),cx,cy+6);ctx.textAlign='left';});
  }catch(error){fail(error.message+'；原稿与批改记录仍保留。');}};image.src=source.image;});}
watch(()=>[props.grade.id,props.question.id,props.grade.result,props.paper.pages],draw,{immediate:true});onBeforeUnmount(()=>{alive=false;sequence++;canvases.clear();});
</script>
<template><section class="student-graded-answer" :data-grade-id="grade.id"><header v-if="!gradingOnly"><strong>{{grade.kind==='initial'?'首次作答与批改':'本次作答与批改'}}</strong><time v-if="at" :datetime="grade.at">{{at}}</time></header><figure v-for="(source,i) in sources" :key="grade.id+':'+i" class="graded-sheet"><canvas :ref="el=>el?canvases.set(i,el):canvases.delete(i)" role="img" :aria-label="'第'+source.page+'页作答与红色批改：'+verdict(result.verdict)" :hidden="!!errors[i]"/><p v-if="errors[i]" class="grade-error" role="status">{{errors[i]}}</p><div class="graded-notes"><template v-if="i===0"><strong>批改记录 · {{verdict(result.verdict)}}</strong><div class="math-prose" v-html="html(result.feedback)"/></template><article v-for="(mark,index) in annotations" :key="'mark:'+index" v-show="mark.page===source.page"><strong>第 {{mark.page}} 页 · 标记 {{index+1}} · {{verdict(mark.kind)}}</strong><div class="math-prose" v-html="html(mark.comment)"/></article><template v-if="i===0"><article v-for="(correction,index) in result.corrections||[]" :key="'correction:'+index"><strong>{{correction.location}}</strong><div v-if="correction.original" class="math-prose" v-html="html('原卷：'+correction.original)"/><div class="math-prose" v-html="html(correction.issue)"/><strong>怎样改</strong><div class="math-prose" v-html="html(correction.correction)"/></article></template></div><figcaption v-if="!gradingOnly">原稿第 {{source.page}} 页</figcaption></figure><section v-if="!sources.length" class="graded-sheet graded-notes"><p v-if="!gradingOnly">{{result.studentAnswer||'本条记录未保存可显示的手写原稿。'}}</p><strong>批改记录 · {{verdict(result.verdict)}}</strong><div class="math-prose" v-html="html(result.feedback)"/><article v-for="(mark,i) in annotations" :key="'mark:'+i"><strong>第 {{mark.page}} 页 · {{verdict(mark.kind)}}</strong><div class="math-prose" v-html="html(mark.comment)"/></article><article v-for="(c,i) in result.corrections||[]" :key="'correction:'+i"><strong>{{c.location}}</strong><div v-if="c.original" class="math-prose" v-html="html('原卷：'+c.original)"/><div class="math-prose" v-html="html(c.issue)"/><strong>怎样改</strong><div class="math-prose" v-html="html(c.correction)"/></article></section><template v-if="!gradingOnly&&sources.length"><Button :aria-expanded="transcription" @click="transcription=!transcription">识别文字</Button><div v-if="transcription" class="math-prose" v-html="html(result.studentAnswer||'未识别到作答')"/></template></section></template>
<style scoped>.student-graded-answer{min-width:0;overflow-wrap:anywhere}.student-graded-answer header{display:flex;gap:12px;flex-wrap:wrap;align-items:center;margin:12px 0;font-size:14px}.student-graded-answer time{color:#68776f}.graded-sheet{margin:14px 0;background:#fff;border:1px solid #e3e6e1;max-width:100%;min-width:0}.graded-sheet canvas{display:block;max-width:100%;width:100%;height:auto}.graded-notes{padding:16px;color:#b42318;font-weight:600;line-height:1.9}.graded-notes article{padding-top:14px}.graded-sheet figcaption{padding:8px 16px;font-size:13px;color:#68776f}.math-prose{white-space:pre-wrap;line-height:1.9;min-width:0}.math-prose :deep(.katex-display){overflow-x:auto;overflow-y:hidden;max-width:100%}.grade-error{color:#b42318;padding:12px}.student-graded-answer.student-graded-answer :deep(.van-button){min-height:44px;font:inherit}</style>

<style scoped>
/* visual-restore-legacy */
.student-graded-answer{margin:20px 0;border:1px solid #d7e0d4;border-radius:10px;background:#fff;overflow:hidden;min-width:0}.student-graded-answer>header{justify-content:space-between;gap:8px;padding:14px 16px;margin:0;border-bottom:1px solid #e2e5dd;font-size:inherit}.student-graded-answer time{font-size:.9em;color:inherit}.graded-sheet{margin:0;border:0;border-radius:0;max-width:800px;margin-inline:auto}.graded-sheet canvas{margin:0 auto}.graded-notes{padding:16px;border-top:1px solid #eedad7;color:#b42318;line-height:1.8}.graded-notes article{margin-top:16px;padding-top:12px;border-top:1px solid #eedad7}.graded-sheet figcaption{padding:0 16px 8px;font-size:inherit;color:inherit}.student-graded-answer.student-graded-answer :deep(.van-button){height:auto;min-height:44px;padding:8px 12px;border:1px solid #bbc8ae;border-radius:8px;background:#f0f4eb;color:#263c30;font:inherit}
</style>
